package fraymus.workspace;
import org.json.*;
import java.util.*;

/** Plots actual native samples and the one-step forecasts from their recorded source ticks. */
final class GoalReport {
    private GoalReport(){}
    static JSONArray checks(JSONObject goal){return new JSONArray()
        .put(new JSONObject().put("selector","#verdict").put("expectText","Physical goal verified"))
        .put(new JSONObject().put("selector","#goal-id").put("expectText",goal.getString("id")))
        .put(new JSONObject().put("selector","#run-id").put("expectText",goal.getString("runId")))
        .put(new JSONObject().put("selector","svg .actual").put("expectCount",1))
        .put(new JSONObject().put("selector","svg .predicted").put("expectCount",1))
        .put(new JSONObject().put("selector","#residuals tr").put("expectCount",29))
        .put(new JSONObject().put("selector","#scope").put("expectText","Native simulation verified. Recorded real-world action use remains unauthorized."));}
    static JSONObject build(JSONObject g,JSONObject r){
        var samples=r.getJSONArray("samples");var innovations=r.getJSONArray("worldInnovations");var rows=new StringBuilder();var actual=new StringBuilder();var predicted=new StringBuilder();double max=Math.max(g.getDouble("targetM")+.2,1.8),sum=0;
        for(Object raw:samples){var s=(JSONObject)raw;actual.append(point(s.getInt("tick"),s.getDouble("distanceM"),max));}
        for(Object raw:innovations){var i=(JSONObject)raw;double p=i.getJSONObject("predicted").getJSONObject("state").getDouble("x"),a=i.getJSONObject("actual").getDouble("distanceM"),e=a-p;sum+=e*e;predicted.append(point(i.getInt("tick"),p,max));rows.append("<tr><td>").append(i.getInt("sourceTick")).append(" → ").append(i.getInt("tick")).append("</td><td>").append(n(p)).append("</td><td>").append(n(a)).append("</td><td>").append(n(e)).append("</td></tr>");}
        var m=r.getJSONObject("worldEvaluation");String svg="<svg viewBox='0 0 800 300' role='img' aria-label='Actual and predicted displacement in metres over 1.5 seconds'><path d='M40 20V260H760' fill='none' stroke='#6b8893'/><text x='40' y='286'>0 s</text><text x='715' y='286'>1.5 s</text><text x='42' y='18'>Displacement (m)</text><polyline class='actual' points='"+actual+"' fill='none' stroke='#18745f' stroke-width='3'/><polyline class='predicted' points='"+predicted+"' fill='none' stroke='#9458bd' stroke-width='2' stroke-dasharray='6 4'/><path d='M256 20V260' stroke='#c36b28' stroke-dasharray='3 4'/><text x='262' y='36'>Disturbance · 0.45 s</text></svg>";
        String html="<!doctype html><html lang='en'><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Verified world goal</title><style>body{margin:0;background:#eef3f2;color:#18352f;font:16px system-ui}main{max-width:1000px;margin:auto;padding:28px}h1{font-size:32px;margin:8px 0}p{line-height:1.5}code{overflow-wrap:anywhere}section{background:white;border:1px solid #b6cbc4;border-radius:14px;padding:20px;margin:16px 0}.metrics{display:flex;gap:24px;flex-wrap:wrap}.metrics b{display:block;font-size:24px}svg{width:100%;background:#f9fbfa}svg text{font:14px system-ui;fill:#355c51}table{border-collapse:collapse;width:100%;font-variant-numeric:tabular-nums}td,th{text-align:left;border-bottom:1px solid #dae5e0;padding:8px}.scope{color:#764722}details{margin-top:20px}</style><main><p>FRAYNIX / JAVA GOAL RUNNER / EDITION 019</p><h1 id='verdict'>Physical goal verified</h1><p>Predict → act → observe → check → retain. This report comes from actual native samples and recorded predictions.</p><section class='metrics'><div><b>"+n(m.getDouble("endpointErrorM"))+" m</b>Endpoint error</div><div><b>"+n(m.getDouble("terminalSpeedMps"))+" m/s</b>Terminal speed</div><div><b>"+n(Math.sqrt(sum/innovations.length()))+" m</b>One-step forecast RMSE</div></section><section>"+svg+"<p>Green: actual displacement. Violet: 50 ms forecasts aligned to their measured ticks. Orange: actual scheduled disturbance. Forecast error is not a confidence interval.</p></section><section><p>Target: "+n(g.getDouble("targetM"))+" m · disturbance: "+n(g.getDouble("disturbanceMps"))+" m/s · model v"+r.getJSONObject("controller").getInt("version")+" · native model actions: "+n(m.getDouble("modelActionFraction")*100)+"%</p><p class='scope' id='scope'>Native simulation verified. Recorded real-world action use remains unauthorized.</p><p>Goal <code id='goal-id'>"+g.getString("id")+"</code><br>Run <code id='run-id'>"+r.getString("id")+"</code><br>Run SHA-256 <code>"+MeasurementStore.hash(r.toString())+"</code></p><details><summary>29 actual forecast checks</summary><table><thead><tr><th>Source → measured tick</th><th>Predicted m</th><th>Actual m</th><th>Residual m</th></tr></thead><tbody id='residuals'>"+rows+"</tbody></table></details></section></main></html>";
        return new JSONObject().put("title","Verified world goal · "+g.getString("id").substring(0,8)).put("files",new JSONObject().put("index.html",html).put("run.json",r.toString(2)).put("procedure.json",new JSONObject().put("kind",GoalRunner.PROCEDURE).put("parameters",g.getJSONObject("parameters")).put("targetM",g.getDouble("targetM")).put("disturbanceMps",g.getDouble("disturbanceMps")).toString(2))).put("sources",new JSONArray(List.of("goal:"+g.getString("id"),"native-run:"+r.getString("id"))));
    }
    private static String n(double x){return String.format(Locale.ROOT,"%.6f",x);}
    private static String point(int tick,double x,double max){return n(40+tick*2.)+","+n(260-x/max*230)+" ";}
}
